package com.pocketagent;

import android.content.Context;
import android.util.AtomicFile;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** A private index; project files are removed only by an explicit, contained deletion. */
final class ProjectStore {
    private static final HashMap<String,java.lang.ref.WeakReference<ProjectStore>> open=new HashMap<>();
    private ProjectStore delegate;
    interface NameTranslator { String translate(String source); }
    private final NameTranslator names;
    private final File file,workspaceBase;
    private JSONObject state;
    private String error="";
    private boolean readOnly;
    ProjectStore(Context context){this(context.getFilesDir(),workspace(context));}
    ProjectStore(File filesDir,File workspace){this(filesDir,workspace,UILocalization::t);}
    ProjectStore(File filesDir,File workspace,NameTranslator translator){names=translator;file=new File(filesDir,"projects.json");workspaceBase=workspace.getAbsoluteFile();synchronized(open){String key=file.getAbsolutePath();try{key=file.getCanonicalPath();}catch(IOException ignored){}java.lang.ref.WeakReference<ProjectStore> ref=open.get(key);ProjectStore existing=ref==null?null:ref.get();if(existing!=null){delegate=existing;return;}load();open.put(key,new java.lang.ref.WeakReference<>(this));}}
    private static File workspace(Context c){UILocalization.initialize(c);File f=c.getExternalFilesDir("workspace");return f==null?new File(c.getFilesDir(),"workspace"):f;}
    synchronized String lastError(){if(delegate!=null)return delegate.lastError();return error;}
    synchronized JSONObject currentProject(){if(delegate!=null)return delegate.currentProject();return copyObject(currentProjectLive());}
    synchronized JSONObject currentChat(){if(delegate!=null)return delegate.currentChat();return copyObject(findChat(currentProjectLive(),state.optString("currentChatID")));}
    synchronized JSONObject currentContext(){if(delegate!=null)return delegate.currentContext();JSONObject project=copyObject(currentProjectLive());return set(set(new JSONObject(),"project",project),"chat",findChat(project,state.optString("currentChatID")));}
    synchronized JSONArray projects(){if(delegate!=null)return delegate.projects();return copyArray(state.optJSONArray("projects"));}
    /** The running task supplies its pinned workspace; UI selection never decides its fence. */
    synchronized JSONArray fileExclusions(String workspace)throws Exception{
        if(delegate!=null)return delegate.fileExclusions(workspace);
        if(readOnly)throw new IOException("项目索引异常，暂不执行文件操作；原文件已保留。");
        if(workspace==null||workspace.isEmpty())throw new IOException("缺少任务工作目录。");
        String root=new File(workspace).getCanonicalPath();JSONArray result=new JSONArray();HashSet<String> seen=new HashSet<>();JSONArray ps=state.optJSONArray("projects");
        for(int i=0;ps!=null&&i<ps.length();i++){JSONObject project=ps.optJSONObject(i);if(project==null||project.optString("workspace").isEmpty())continue;String other=new File(project.getString("workspace")).getCanonicalPath();if(other.startsWith(root+File.separator)&&seen.add(other))result.put(other);}
        return result;
    }
    /** Caller arguments cannot replace the authoritative outer IPC workspace or exclusions. */
    synchronized JSONObject scopedFileOperation(String workspace,String name,JSONObject args)throws Exception{
        if(delegate!=null)return delegate.scopedFileOperation(workspace,name,args);
        return new JSONObject().put("kind","tool").put("workspace",workspace).put("name",name).put("args",args==null?new JSONObject():new JSONObject(args.toString())).put("file_exclusions",fileExclusions(workspace));
    }
    private JSONObject currentProjectLive(){return findProject(state.optString("currentProjectID"));}

    synchronized boolean selectProject(String id){if(delegate!=null)return delegate.selectProject(id);JSONObject project=findProject(id);if(project==null)return false;JSONObject before=copyObject(state);set(state,"currentProjectID",id);set(state,"currentChatID",latestChatId(project));return commit(before);}
    synchronized boolean selectChat(String id){if(delegate!=null)return delegate.selectChat(id);JSONArray ps=state.optJSONArray("projects");if(ps!=null)for(int i=0;i<ps.length();i++){JSONObject p=ps.optJSONObject(i);if(findChat(p,id)!=null){JSONObject before=copyObject(state);set(p,"currentChatID",id);set(state,"currentProjectID",p.optString("id"));set(state,"currentChatID",id);return commit(before);}}return false;}
    synchronized JSONObject createProject(String name){if(delegate!=null)return delegate.createProject(name);if(readOnly)return null;JSONObject before=copyObject(state);JSONArray ps=state.optJSONArray("projects");String id=newId();JSONObject p=project(id,clean(name,names.translate("项目 {number}").replace("{number}",Integer.toString(ps.length()+1)),60),new File(new File(workspaceBase,"Projects"),id));ps.put(p);set(state,"currentProjectID",id);set(state,"currentChatID",p.optString("currentChatID"));return commit(before)?copyObject(p):null;}
    synchronized JSONObject createChat(){if(delegate!=null)return delegate.createChat();JSONObject p=currentProjectLive();if(p==null||readOnly)return null;JSONObject before=copyObject(state);JSONArray cs=p.optJSONArray("chats");if(cs==null){cs=new JSONArray();set(p,"chats",cs);}JSONObject c=newChat(names.translate("新对话 {number}").replace("{number}",Integer.toString(cs.length()+1)));cs.put(c);set(p,"currentChatID",c.optString("id"));set(state,"currentChatID",c.optString("id"));return commit(before)?copyObject(c):null;}
    synchronized boolean renameProject(String id,String name){if(delegate!=null)return delegate.renameProject(id,name);JSONObject p=findProject(id);String value=clean(name,"",60);if(p==null||value.isEmpty())return false;JSONObject before=copyObject(state);set(p,"name",value);set(p,"updated",System.currentTimeMillis());return commit(before);}
    synchronized boolean renameChat(String id,String title){if(delegate!=null)return delegate.renameChat(id,title);String value=clean(title,"",120);if(value.isEmpty())return false;JSONArray ps=state.optJSONArray("projects");for(int i=0;i<ps.length();i++){JSONObject c=findChat(ps.optJSONObject(i),id);if(c!=null){JSONObject before=copyObject(state);set(c,"title",value);set(c,"titleManuallySet",true);set(c,"autoTitle",false);set(c,"updated",System.currentTimeMillis());return commit(before);}}return false;}
    synchronized void saveCurrent(JSONArray history,String transcript){if(delegate!=null){delegate.saveCurrent(history,transcript);return;}JSONObject p=currentProjectLive();if(p!=null)saveChat(p.optString("id"),state.optString("currentChatID"),history,transcript);}
    synchronized boolean saveChat(String projectId,String chatId,JSONArray history,String transcript){if(delegate!=null)return delegate.saveChat(projectId,chatId,history,transcript);JSONObject p=findProject(projectId),c=findChat(p,chatId);if(c==null)return false;JSONArray h=history==null?new JSONArray():copyArray(history);if(h.toString().getBytes(StandardCharsets.UTF_8).length>700*1024){error="对话上下文超过 700 KiB，请新建对话；原记录已保留。";return false;}String t=transcript==null?"":transcript;if(t.length()>120000)t=t.substring(t.length()-120000);JSONObject before=copyObject(state);set(c,"history",h);set(c,"transcript",t);set(c,"updated",System.currentTimeMillis());set(p,"updated",System.currentTimeMillis());if(!c.optBoolean("titleManuallySet")&&c.optBoolean("autoTitle",c.optString("title").matches("新对话(?: [0-9]+)?"))){for(int i=0;i<h.length();i++){JSONObject item=h.optJSONObject(i);if(item!=null&&"user".equals(item.optString("role"))){String title=item.optString("content","").replace('\n',' ').trim();if(!title.isEmpty()){set(c,"title",title.length()>36?title.substring(0,36)+"…":title);set(c,"autoTitle",false);}break;}}}return commit(before);}

    /** Delete only selected chat records. An emptied project receives one new empty chat. */
    synchronized int deleteChats(Collection<String> ids){if(delegate!=null)return delegate.deleteChats(ids);if(ids==null||ids.isEmpty()||readOnly)return 0;HashSet<String> selected=new HashSet<>(ids);JSONObject before=copyObject(state);int count=0;JSONArray ps=state.optJSONArray("projects");for(int i=0;i<ps.length();i++){JSONObject p=ps.optJSONObject(i);JSONArray old=p.optJSONArray("chats"),keep=new JSONArray();if(old!=null)for(int j=0;j<old.length();j++){JSONObject c=old.optJSONObject(j);if(c==null)continue;if(selected.contains(c.optString("id")))count++;else keep.put(c);}if(keep.length()==0)keep.put(newChat(names.translate("新对话")));set(p,"chats",keep);if(findChat(p,p.optString("currentChatID"))==null)set(p,"currentChatID",latestChatId(p));}if(count==0){state=before;return 0;}normalizeSelection();return commit(before)?count:0;}
    /** Record-only unless deleteFiles is true. Returns counts plus any protected/failed paths. */
    synchronized JSONObject deleteProjects(Collection<String> ids,boolean deleteFiles){if(delegate!=null)return delegate.deleteProjects(ids,deleteFiles);JSONObject result=new JSONObject();JSONArray errors=new JSONArray(),removed=new JSONArray();if(ids==null||ids.isEmpty()||readOnly)return set(set(result,"deleted",0),"file_errors",errors);HashSet<String> selected=new HashSet<>(ids);JSONObject before=copyObject(state);JSONArray old=state.optJSONArray("projects"),keep=new JSONArray();for(int i=0;i<old.length();i++){JSONObject p=old.optJSONObject(i);if(p==null)continue;if(selected.contains(p.optString("id")))removed.put(copyObject(p));else keep.put(p);}if(removed.length()==0)return set(set(result,"deleted",0),"file_errors",errors);if(keep.length()==0){String id=newId();keep.put(project(id,names.translate("默认项目"),new File(new File(workspaceBase,"Projects"),id)));}set(state,"projects",keep);normalizeSelection();if(!commit(before))return set(set(result,"deleted",0),"file_errors",errors.put(lastError()));if(deleteFiles)for(int i=0;i<removed.length();i++){JSONObject p=removed.optJSONObject(i);try{deleteOwnedWorkspace(p);}catch(Exception e){errors.put(p.optString("name")+"："+e.getMessage());}}return set(set(set(result,"deleted",removed.length()),"files_requested",deleteFiles),"file_errors",errors);}
    synchronized JSONObject deleteProject(String id,boolean deleteFiles){return deleteProjects(Collections.singleton(id),deleteFiles);}
    synchronized int deleteChat(String id){return deleteChats(Collections.singleton(id));}

    private void deleteOwnedWorkspace(JSONObject p)throws IOException{String id=p.optString("id");if(!id.matches("[0-9a-fA-F-]{36}"))throw new IOException("目录身份无效，文件已保留");File expected=new File(new File(workspaceBase.getCanonicalFile(),"Projects"),id);File supplied=new File(p.optString("workspace"));if(!supplied.getCanonicalFile().equals(expected.getAbsoluteFile())||!expected.getCanonicalFile().equals(expected.getAbsoluteFile()))throw new IOException("原工作目录不是本应用创建的独立项目目录，文件已保留");if(expected.exists())deleteTree(expected,expected.getCanonicalPath());}
    private static void deleteTree(File f,String root)throws IOException{File lexical=new File(f.getParentFile().getCanonicalFile(),f.getName());if(!f.getCanonicalFile().equals(lexical)){if(!f.delete())throw new IOException("无法删除目录中的链接");return;}String path=f.getCanonicalPath();if(!path.equals(root)&&!path.startsWith(root+File.separator))throw new IOException("拒绝跨出项目目录");if(f.isDirectory()){File[] children=f.listFiles();if(children==null)throw new IOException("目录不可读");for(File child:children)deleteTree(child,root);}if(!f.delete())throw new IOException("无法删除 "+f.getName());}
    private void normalizeSelection(){JSONObject p=currentProjectLive();if(p==null){p=state.optJSONArray("projects").optJSONObject(0);set(state,"currentProjectID",p.optString("id"));}set(state,"currentChatID",latestChatId(p));set(p,"currentChatID",state.optString("currentChatID"));}
    private String latestChatId(JSONObject p){String active=p.optString("currentChatID");if(findChat(p,active)!=null)return active;JSONArray cs=p.optJSONArray("chats");if(cs==null||cs.length()==0){cs=new JSONArray();JSONObject c=newChat(names.translate("新对话"));cs.put(c);set(p,"chats",cs);return c.optString("id");}JSONObject latest=cs.optJSONObject(cs.length()-1);return latest==null?"":latest.optString("id");}
    private JSONObject project(String id,String name,File workspace){JSONObject p=new JSONObject(),c=newChat(names.translate("新对话"));set(p,"id",id);set(p,"name",name);set(p,"workspace",workspace.getAbsolutePath());set(p,"chats",new JSONArray().put(c));set(p,"currentChatID",c.optString("id"));set(p,"created",System.currentTimeMillis());set(p,"updated",System.currentTimeMillis());return p;}
    private void load(){try{AtomicFile index=new AtomicFile(file);if(file.exists()||new File(file.getPath()+".bak").exists()){try(InputStream in=index.openRead()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>16*1024*1024)throw new IOException("项目索引超过 16 MiB");out.write(b,0,n);}state=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}if(state.optJSONArray("projects")==null)throw new IOException("项目索引格式无效");}}catch(Exception e){error="无法读取项目记录，原文件已保留："+e.getMessage();readOnly=true;state=null;}if(state==null||state.optJSONArray("projects").length()==0){state=new JSONObject();String id=newId();JSONObject p=project(id,names.translate("默认项目"),new File(new File(workspaceBase,"Projects"),id));set(state,"projects",new JSONArray().put(p));set(state,"currentProjectID",id);set(state,"currentChatID",p.optString("currentChatID"));if(!readOnly)persist();}normalizeSelection();}
    private boolean commit(JSONObject before){if(readOnly){state=before;return false;}if(persist())return true;state=before;return false;}
    private boolean persist(){AtomicFile index=new AtomicFile(file);FileOutputStream out=null;try{byte[] data=state.toString().getBytes(StandardCharsets.UTF_8);if(data.length>16*1024*1024)throw new IOException("项目索引超过 16 MiB");File parent=file.getParentFile();if(parent!=null&&!parent.exists()&&!parent.mkdirs())throw new IOException("无法创建项目目录");out=index.startWrite();out.write(data);index.finishWrite(out);error="";return true;}catch(Exception e){if(out!=null)index.failWrite(out);error="保存项目失败："+e.getMessage();return false;}}
    private JSONObject findProject(String id){JSONArray ps=state==null?null:state.optJSONArray("projects");if(ps!=null)for(int i=0;i<ps.length();i++){JSONObject p=ps.optJSONObject(i);if(p!=null&&p.optString("id").equals(id))return p;}return null;}
    private JSONObject findChat(JSONObject p,String id){JSONArray cs=p==null?null:p.optJSONArray("chats");if(cs!=null)for(int i=0;i<cs.length();i++){JSONObject c=cs.optJSONObject(i);if(c!=null&&c.optString("id").equals(id))return c;}return null;}
    private JSONObject newChat(String title){JSONObject c=new JSONObject();set(c,"id",newId());set(c,"title",title);set(c,"autoTitle",true);set(c,"history",new JSONArray());set(c,"transcript","");set(c,"created",System.currentTimeMillis());set(c,"updated",System.currentTimeMillis());return c;}
    private static String clean(String v,String fallback,int max){String s=v==null?"":v.trim();if(s.isEmpty())s=fallback;return s.length()>max?s.substring(0,max):s;}
    private static String newId(){return UUID.randomUUID().toString().toLowerCase(Locale.ROOT);}
    private static JSONObject set(JSONObject j,String k,Object v){try{j.put(k,v);}catch(Exception ignored){}return j;}
    private static JSONObject copyObject(JSONObject j){try{return j==null?null:new JSONObject(j.toString());}catch(Exception e){return null;}}
    private static JSONArray copyArray(JSONArray a){try{return a==null?new JSONArray():new JSONArray(a.toString());}catch(Exception e){return new JSONArray();}}
}
